function findMaxCounting(numbers) {
  let comparisons = 0;
  let max = numbers[0];
  for (let i = 1; i < numbers.length; i++) {
    comparisons++;
    if (numbers[i] > max) max = numbers[i];
  }
  return { max, comparisons };
}

for (const n of [10, 100, 1000]) {
  const data = Array.from({ length: n }, (_, i) => i);
