function linearSearch(sorted, target) {
  for (let i = 0; i < sorted.length; i++) if (sorted[i] === target) return i; // O(n)
  return -1;
}

function binarySearch(sorted, target) {
  let low = 0, high = sorted.length - 1;
  while (low <= high) {                       // cada vuelta descarta la mitad: O(log n)
    const mid = Math.floor((low + high) / 2);
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) low = mid + 1; else high = mid - 1;
  }
  return -1;
}

const data = Array.from({ length: 1000 }, (_, i) => i * 2);
console.log(linearSearch(data, 1998), binarySearch(data, 1998)); // 999 999

// 1) Fuerza bruta: O(n²) tiempo, O(1) memoria
function hasDuplicatesBrute(list) {
  for (let i = 0; i < list.length; i++)
    for (let j = i + 1; j < list.length; j++)
      if (list[i] === list[j]) return true;
  return false;
}

// 2) Ordenar y comparar vecinos: O(n log n) tiempo, O(n) memoria por la copia
function hasDuplicatesSort(list) {
  const copy = [...list].sort((a, b) => a - b);
  for (let i = 1; i < copy.length; i++) if (copy[i] === copy[i - 1]) return true;
  return false;
}

// 3) Set: O(n) tiempo, O(n) memoria
function hasDuplicatesSet(list) {
  return new Set(list).size !== list.length;
}

const sample = [3, 1, 4, 1, 5];
console.log(hasDuplicatesBrute(sample), hasDuplicatesSort(sample), hasDuplicatesSet(sample)); // true true true

