class Account {
  #balance = 0;                          // campo privado de verdad
  constructor(owner) { this.owner = owner; }
  deposit(amount) {
    if (amount <= 0) throw new RangeError("El importe debe ser positivo");
    this.#balance += amount;
    return this;
  }
  get balance() { return this.#balance; }
  toString() { return `${this.owner}: ${this.#balance}`; }
}

class SavingsAccount extends Account {
  constructor(owner, rate) { super(owner); this.rate = rate; }
  addInterest() { return this.deposit(this.balance * this.rate); }
}

