const wait = (ms, value) => new Promise((resolve) => setTimeout(() => resolve(value), ms));

async function main() {
  let t = Date.now();
  const a = await wait(100, "A");
  const b = await wait(100, "B");           // espera a que termine A
  console.log(a + b, Date.now() - t >= 190); // AB true  (≈200 ms)

  t = Date.now();
  const [c, d] = await Promise.all([wait(100, "C"), wait(100, "D")]); // en paralelo
  console.log(c + d, Date.now() - t < 190);  // CD true  (≈100 ms)
}
main();

