async canActivate(context: ExecutionContext): Promise<boolean> {
  const request = context.switchToHttp().getRequest<AuthenticatedRequest>();
  const token =
    extractBearerToken(request.headers.authorization) ??
    readCookie(request.headers.cookie, ACCESS_TOKEN_COOKIE);

  if (!token) {
    throw new UnauthorizedException("Debes iniciar sesión para continuar");
  }

  request.user = await this.tokens.verifyAccessToken(token);
  return true;
}

export const BCRYPT_COST = 12;

async function hashContrasena(plain: string): Promise<string> {
  return bcrypt.hash(plain, BCRYPT_COST);
}

async function verificarContrasena(plain: string, hash: string): Promise<boolean> {
  try {
    return await bcrypt.compare(plain, hash);
  } catch {
    return false; // hash corrupto o de otro algoritmo: tratarlo como 'no coincide'
  }
}

@Patch(":id")
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles("instructor", "admin")
async actualizar(@Param("id") id: string, @Req() req: AuthenticatedRequest, @Body() body: ActualizarCursoDto) {
  const curso = await this.cursosService.buscar(id);
  if (!curso) throw new NotFoundException();

  const esAdmin = req.user.rol === "admin";
  const esDueño = curso.instructorId === req.user.sub;
  if (!esAdmin && !esDueño) {
    throw new ForbiddenException("No puedes editar un curso que no es tuyo");
  }

  return this.cursosService.actualizar(id, body);
}

export const Roles = (...roles: string[]) => SetMetadata("roles", roles);

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const rolesRequeridos = this.reflector.get<string[]>("roles", context.getHandler());
    if (!rolesRequeridos?.length) return true; // sin @Roles, no se restringe por rol

    const { user } = context.switchToHttp().getRequest<AuthenticatedRequest>();
    if (!rolesRequeridos.includes(user.rol)) {
      throw new ForbiddenException("No tienes permiso para esta acción");
    }
    return true;
  }
}

